import {HOUSE_UPGRADES,HOUSE_SKILLS,HOUSE_REQUESTS,houseLevel,houseProtection,houseMaxHealth,batteryCapacity,cookingCost} from './house-systems.js';
export const HOUSE_HOTSPOTS=[
 {key:'stove',name:'Stove',tab:'kitchen',x:114,y:490,w:79,h:144},
 {key:'sink',name:'Kitchen sink',tab:'kitchen',x:204,y:477,w:220,h:59},
 {key:'pantry',name:'Pantry',tab:'kitchen',x:442,y:433,w:123,h:146},
 ...[100,340,706,946].map((x,i)=>({key:'beds',name:['West bedroom','Garden bedroom','East bedroom','Loft bedroom'][i],tab:'bedrooms',x,y:238,w:234,h:138})),
 {key:'medicine',name:'Medical cabinet',tab:'care',x:889,y:178,w:39,h:35},
 {key:'common',name:'Common room',tab:'overview',x:738,y:551,w:290,h:105},
 {key:'library',name:'Bookshelf',tab:'library',x:994,y:428,w:62,h:74},
 {key:'battery',name:'Emergency battery',tab:'overview',x:1031,y:535,w:33,h:53},
 {key:'memory',name:'Memory wall',tab:'memories',x:597,y:303,w:55,h:58},
 {key:'doors',name:'Door and window fortification',tab:'overview',x:617,y:655,w:69,h:23},
];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const costLabel=cost=>Object.entries(cost).map(([k,v])=>v+' '+({meals:'prepared meal',keepsakes:'keepsake'}[k]||k)).join(' + ');
const home=p=>!p.expeditionId&&!(p.away>0);
const button=(label,attrs='',disabled=false)=>`<button type="button" ${attrs} ${disabled?'disabled':''}>${label}</button>`;

export function createHousePanel({game,dialog,render,message,sync}){
 let tab='overview',memoryPage=0;
 const tabs={overview:'Rooms',kitchen:'Kitchen',bedrooms:'Bedrooms',care:'Care',library:'Library',requests:'Requests',memories:'Memories'};
 function card(key){
  const s=game.s,spec=HOUSE_UPGRADES[key],q=game.houseUpgradeQuote(key),current=spec.levels[q.level-1];
  return `<article class="house-upgrade" id="house-upgrade-${key}" data-house-card="${key}"><div class="house-card-heading"><span class="house-item-mark mark-${key}" aria-hidden="true"></span><div><small>${esc(spec.room)}</small><h4>${esc(spec.name)}</h4></div><span class="house-level">${q.level?'LEVEL '+q.level:'UNBUILT'}</span></div><p>${esc(spec.about)}</p><p class="house-benefit">${esc(current?.text||'No backup installed')}</p>${q.next?`<div class="house-next"><small>NEXT · LEVEL ${q.level+1}</small><strong>${esc(q.next.text)}</strong></div>${button('Upgrade · '+q.cost+' scrap',`data-house-upgrade="${key}"`,!q.available)}`:'<span class="house-complete">Fully upgraded</span>'}<small class="house-reason">${esc(q.reason)}</small></article>`;
 }
 const stock=()=>`<div class="house-resources"><span>Scrap <b>${game.s.scrap}</b></span><span>Food <b>${game.s.food}</b></span><span>Water <b>${game.s.water}</b></span><span>Medicine <b>${game.s.meds}</b></span></div>`;
 function project(){const q=game.s.house.project;return q?`<section class="house-project"><div><strong>${esc(HOUSE_UPGRADES[q.key].name)} · level ${q.level}</strong><span>${Math.floor(q.progress*100)}% installed · builder works during daylight</span></div><progress value="${q.progress}" max="1" aria-label="House improvement progress"></progress>${button('Cancel project','data-house-cancel')}</section>`:'';}
 function kitchen(){const s=game.s,q=game.householdQuote(),h=game.homesteadStatus(),batch=cookingCost(s,4);return `<section class="house-kitchen-order"><p class="eyebrow">TOMORROW'S TABLE</p><h4>Prepare breakfast for the household</h4><p>${s.people.filter(home).length} people at home · ${h.meals}/${h.mealCap} meals ready · ${h.pantry}/${h.pantryCap} preserved rations</p><p>${q.portions?`${q.portions} more portions cost <strong>${costLabel(q.cost)}</strong>.`:'Enough meals are already on the shelf.'} Drinking water and big appetites are supplied separately at breakfast.</p>${button('Prepare '+q.portions+' portions','data-house-batch',!q.available)}<small>${esc(q.reason)}</small><hr><p>A batch of four uses <strong>${costLabel(batch)}</strong>.</p>${button('Cook 4 meals','data-house-four',s.food<batch.food||s.water<batch.water||h.meals+4>h.mealCap)} ${button('Kitchen & rations','data-house-original-kitchen')}</section><div class="house-upgrades">${['stove','sink','pantry'].map(card).join('')}</div>`;}
 function bedrooms(){const s=game.s;return `<p>Each survivor has one assigned bed, reserved while they travel. Bed comfort helps fed survivors once each morning.</p><div class="house-bed-grid">${s.house.beds.map((id,i)=>{const p=s.people.find(p=>p.id===id),possessions=s.house.possessions.filter(x=>x.personId===id);return `<article class="house-bed"><span class="house-bed-icon blanket-${i%4}" aria-hidden="true"></span><div><label for="house-bed-${i}">${['West','Garden','East','Loft'][Math.floor(i/2)]} room · bed ${i%2+1}</label><select id="house-bed-${i}" data-house-bed="${i}"><option value="" ${id===null?'selected':''} disabled>Unassigned</option>${s.people.map(p=>`<option value="${p.id}" ${p.id===id?'selected':''}>${esc(p.name)}${home(p)?'':' · away'}</option>`).join('')}</select><small>${p?`${Math.ceil(p.hp)}/${p.maxHp} health`:'A place for someone new'}</small>${possessions.length?'<small>'+esc(HOUSE_REQUESTS[possessions.at(-1).type].possession)+'</small>':''}</div></article>`;}).join('')}</div><div class="house-upgrades">${card('beds')}</div>`;}
 function care(){const s=game.s,amount=50+(houseLevel(s,'medicine')-1)*15;return `<p>One medicine restores up to ${amount} health. The patient must be at home.</p><div class="house-patients">${s.people.map(p=>`<article><div><strong>${esc(p.name)}</strong><span>${Math.ceil(p.hp)} / ${p.maxHp} health${home(p)?'':' · away'}</span><meter min="0" max="${p.maxHp}" value="${p.hp}" aria-label="${esc(p.name)} health"></meter></div>${button('Treat · 1 medicine',`data-house-treat="${p.id}"`,!home(p)||p.hp>=p.maxHp||s.meds<1)}</article>`).join('')}</div><div class="house-upgrades">${card('medicine')}</div>`;}
 function library(){const s=game.s,people=s.people.filter(home),xp=houseLevel(s,'library')*2;return `<section class="house-kitchen-order"><p class="eyebrow">A QUIET MOMENT</p><h4>Learn from what we find</h4><p>The farming notebook is here from the start. Returning expeditions bring new manuals and keepsakes. Each fed survivor can study once each morning for ${xp} XP.</p><div class="house-study"><label>Survivor<select id="house-study-person">${people.map(p=>`<option value="${p.id}" ${s.house.studied[p.id]===s.day?'disabled':''}>${esc(p.name)}${s.house.studied[p.id]===s.day?' · studied':''}</option>`).join('')}</select></label><label>Manual<select id="house-study-skill">${s.house.manuals.map(k=>`<option value="${k}">${HOUSE_SKILLS[k]}</option>`).join('')}</select></label>${button('Study','data-house-study',!people.some(p=>s.house.studied[p.id]!==s.day&&s.breakfast?.fed.includes(p.name)))}</div></section><div class="house-upgrades">${card('library')}</div>`;}
 function requests(){const s=game.s,h=s.house,r=h.request,p=s.people.find(p=>p.id===r?.personId),spec=HOUSE_REQUESTS[r?.type],enough=spec&&Object.entries(spec.cost).every(([k,n])=>(k==='meals'?s.homestead.meals:k==='keepsakes'?h.keepsakes:s[k])>=n);return `<p>Small requests make this house their home. ${h.requestsDone} fulfilled · ${h.keepsakes} keepsakes on the shelf.</p>${p?`<article class="house-request"><p class="eyebrow">${esc(p.name)} ASKS</p><h4>${esc(spec.name)}</h4><blockquote>“${esc(spec.text)}”</blockquote><p>Costs ${costLabel(spec.cost)} · +6 morale for ${esc(p.name)}</p><p>Adds: ${esc(spec.possession)} beside their bed.</p>${button('Fulfill request','data-house-request',!enough||!home(p))}<small>${home(p)?enough?'Ready to give.':'Gather the requested supplies first.':'Waiting for their return.'}</small></article>`:'<p class="house-complete">Everyone is settled for now. Another request may appear next morning.</p>'}<div class="house-possession-list">${h.possessions.slice(-12).reverse().map(item=>`<span>${esc(s.people.find(p=>p.id===item.personId)?.name||'A former survivor')} · ${esc(HOUSE_REQUESTS[item.type].possession)}</span>`).join('')}</div>`;}
 function memories(){const all=game.s.house.memories.slice().reverse();memoryPage=Math.min(memoryPage,Math.max(0,Math.ceil(all.length/12)-1));return `<p>Our first harvest, the people who joined us, the hordes we survived, and those we remember.</p><div class="house-memory-wall">${all.slice(memoryPage*12,memoryPage*12+12).map(m=>`<article class="house-memory memory-${m.kind}"><span class="memory-picture" aria-hidden="true"><i></i></span><small>DAY ${m.day} · ${esc(m.kind.toUpperCase())}</small><p>${esc(m.text)}</p></article>`).join('')||'<p>The first memories will appear as the farm grows.</p>'}</div><div class="house-memory-pages">${button('← Newer','data-house-memory-page="-1"',memoryPage===0)}<span>${all.length} memories · page ${memoryPage+1}</span>${button('Older →','data-house-memory-page="1"',(memoryPage+1)*12>=all.length)}</div>`;}
 function overview(){const s=game.s;return `<div class="house-status"><div><small>FARMHOUSE</small><strong>${Math.ceil(s.farmHp)} / ${houseMaxHealth(s)} HP</strong><span>${Math.round(houseProtection(s)*100)}% damage protection</span></div><div><small>BACKUP LIGHTING</small><strong>${Math.floor(s.house.charge)} / ${batteryCapacity(s)} sec</strong><span>${!batteryCapacity(s)?'No backup battery installed':game.powered()?'Generator charging the battery':s.house.charge>0?'Indoor backup ready':'Generator needed to recharge'}</span></div><div><small>DAILY LIFE</small><strong>${s.people.filter(home).length} at home</strong><span>Meals · reading · conversation · rest</span></div></div><p class="house-intro-note">Choose an improvement. Builders install it during daylight. The room changes when the work is finished.</p><div class="house-upgrades">${['doors','shutters','common','battery','stove','sink','pantry','beds','medicine','library'].map(card).join('')}</div>`;}
 function html(){return `<section class="house-panel"><div class="house-panel-heading"><div><p class="eyebrow">INSIDE THE FARMHOUSE</p><h3>A home worth keeping.</h3></div><span>DAY ${game.s.day+1}</span></div>${stock()}${project()}<nav class="house-room-tabs" aria-label="House rooms">${Object.entries(tabs).map(([key,label])=>button(label,`data-house-tab="${key}" aria-current="${tab===key?'page':'false'}"`)).join('')}</nav><div class="house-room-content">${({overview,kitchen,bedrooms,care,library,requests,memories}[tab]||overview)()}</div></section>`;}
 function handleClick(e){const b=e.target.closest('button');if(!b)return false;let result;
  if(b.dataset.houseTab){tab=b.dataset.houseTab;render();return true;}
  if(b.dataset.houseUpgrade)result=game.orderHouseUpgrade(b.dataset.houseUpgrade);
  else if(b.hasAttribute('data-house-cancel'))result=game.cancelHouseUpgrade();
  else if(b.hasAttribute('data-house-batch'))result=game.prepareHousehold();
  else if(b.hasAttribute('data-house-four'))result=game.cookHouseBatch(4);
  else if(b.dataset.houseTreat)result=game.treatAtHome(Number(b.dataset.houseTreat));
  else if(b.hasAttribute('data-house-study'))result=game.studyAtHome(Number(dialog.querySelector('#house-study-person')?.value),dialog.querySelector('#house-study-skill')?.value);
  else if(b.hasAttribute('data-house-request'))result=game.fulfillHouseRequest();
  else if(b.dataset.houseMemoryPage){memoryPage=Math.max(0,memoryPage+Number(b.dataset.houseMemoryPage));render();return true;}
  else return false;
  render();message(result.message);sync();return true;
 }
 function handleChange(e){if(e.target.matches('[data-house-bed]')){const r=game.assignHouseBed(Number(e.target.value),Number(e.target.dataset.houseBed));render();message(r.message);sync();}}
 function focus(next='overview',key){tab=Object.hasOwn(tabs,next)?next:'overview';render();if(key)dialog.querySelector('#house-upgrade-'+key)?.scrollIntoView({block:'nearest'});}
 return {html,handleClick,handleChange,focus,project};
}

export function installHouseHotspots({open}){
 const layer=document.createElement('div');layer.id='house-hotspots';layer.className='house-hotspots';layer.setAttribute('aria-label','Farmhouse objects');layer.hidden=true;
 layer.innerHTML=HOUSE_HOTSPOTS.map((spot,i)=>`<button type="button" data-house-spot="${i}" aria-label="${esc(spot.name)}" title="${esc(spot.name)}" style="left:${spot.x/12.8}%;top:${spot.y/7.2}%;width:${spot.w/12.8}%;height:${spot.h/7.2}%"><span>${esc(spot.name)}</span></button>`).join('');
 document.querySelector('.game-stage').append(layer);
 layer.addEventListener('click',e=>{const b=e.target.closest('[data-house-spot]');if(b){const spot=HOUSE_HOTSPOTS[Number(b.dataset.houseSpot)];open(spot.tab,spot.key);}});
 const refresh=()=>layer.hidden=document.querySelector('#house-overlay').hidden;new MutationObserver(refresh).observe(document.querySelector('#house-overlay'),{attributes:true,attributeFilter:['hidden']});refresh();
}
